.chapter-workbench {
  --ink: #2C3E50;
  --muted: #7F8C8D;
  --accent: #2C5F68;
  --warm: #D97742;
  --line: #E0E0E0;
  --paper: #F5F5F7;
  --bg-card: #FFFFFF;

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
  box-sizing: border-box;
}

.chapter-workbench * {
  box-sizing: border-box;
}

.chapter-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
}

.chapter-header h1 {
  font-size: 2rem;
  margin: 0 0 0.5rem 0;
  color: var(--accent);
}

.lead-text {
  font-size: 1.125rem;
  color: var(--muted);
  max-width: 800px;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
  }
}

.data-panel, .viz-panel {
  background: var(--bg-card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
}

.panel-header h2 {
  font-size: 1.25rem;
  margin: 0;
  color: var(--ink);
}

.table-container {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 4px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
  min-width: 600px;
}

th, td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

th {
  background: #F9FAFB;
  font-weight: 600;
  color: var(--muted);
  white-space: nowrap;
}

tr:last-child td {
  border-bottom: none;
}

.table-notes {
  font-size: 0.75rem;
  color: var(--muted);
  border-top: 1px solid var(--line);
  padding-top: 0.5rem;
}

.viz-card {
  background: #FAFAFA;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem;
  flex: 1;
}

.viz-card h3 {
  font-size: 1rem;
  margin: 0 0 0.75rem 0;
  color: var(--accent);
}

.viz-card p {
  font-size: 0.875rem;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.highlight-orange {
  border-left: 4px solid var(--warm);
  background: #FFFBF7;
}

.stat-block {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #FFF;
  padding: 0.75rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  margin-bottom: 1rem;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--muted);
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--warm);
}

.chart-container {
  position: relative;
  height: 200px;
  width: 100%;
  margin-bottom: 0.5rem;
}

.chart-legend {
  display: flex;
  gap: 1rem;
  font-size: 0.75rem;
  color: var(--muted);
  justify-content: center;
}

.dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 4px;
}

.dot.before { background: #BDC3C7; }
.dot.after { background: var(--accent); }

.chart-desc {
  font-size: 0.75rem;
  text-align: center;
  margin-top: 0.5rem;
  color: var(--muted);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.source-btn:hover {
  background: var(--accent);
  color: #FFF;
}

.source-btn.small {
  padding: 0.15rem 0.4rem;
  font-size: 0.7rem;
  margin-top: 0.5rem;
}

.limitations-box {
  background: #F0F4F8;
  border: 1px solid #D1D9E6;
  border-radius: 6px;
  padding: 1rem;
  font-size: 0.875rem;
}

.limitations-box h4 {
  margin: 0 0 0.5rem 0;
  color: var(--ink);
  font-size: 1rem;
}

.limitations-box ul {
  margin: 0;
  padding-left: 1.25rem;
  color: var(--muted);
}

.limitations-box li {
  margin-bottom: 0.25rem;
}
