(function() {
  const tables = window.paperMindData?.tables || [];
  const tableData = tables.find(t => t.id === 'p41-Table_1');

  // 1. 填充表格
  const tbody = document.querySelector('#inequality-table tbody');
  if (tableData && tbody) {
    tableData.rows.forEach(row => {
      const tr = document.createElement('tr');

      // 辅助函数：安全获取数值，null 显示为 '-'，非数字原样显示
      const getVal = (key) => {
        const val = row.values[key];
        if (val === null || val === undefined) return '-';
        // 尝试转换为百分比显示，如果是小数
        const num = Number(val);
        if (!isNaN(num) && Math.abs(num) < 1 && key.includes('effect')) {
           return (num * 100).toFixed(1) + '%';
        }
        return val;
      };

      const cols = [
        row.label,
        getVal('(1) Baseline AI exposure'),
        getVal('(2) Direct effect of AI exposure'),
        getVal('(3) Total wage effect of AI exposure'),
        getVal('(4) Exposure to easy tasks'),
        getVal('(5) Exposure to hard tasks'),
        getVal('(7) Total wage effect of exposure to easy and hard tasks')
      ];

      cols.forEach(text => {
        const td = document.createElement('td');
        td.textContent = text;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
  }

  // 2. 绘制不平等标准差图表 (Canvas)
  const canvas = document.getElementById('inequality-canvas');
  if (canvas) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const padding = 40;

    // 清空画布
    ctx.clearRect(0, 0, width, height);

    // 数据：0.35 -> 0.36
    const valBefore = 0.35;
    const valAfter = 0.36;
    const maxVal = 0.40;
    const minVal = 0.30;

    const x1 = padding + 50;
    const x2 = width - padding - 50;
    const yScale = (height - 2 * padding) / (maxVal - minVal);

    const y1 = height - padding - (valBefore - minVal) * yScale;
    const y2 = height - padding - (valAfter - minVal) * yScale;

    // 绘制坐标轴
    ctx.beginPath();
    ctx.strokeStyle = '#E0E0E0';
    ctx.lineWidth = 1;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 绘制柱状/点
    ctx.fillStyle = '#BDC3C7';
    ctx.beginPath();
    ctx.arc(x1, y1, 6, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#2C5F68';
    ctx.beginPath();
    ctx.arc(x2, y2, 6, 0, Math.PI * 2);
    ctx.fill();

    // 连线
    ctx.beginPath();
    ctx.strokeStyle = '#2C5F68';
    ctx.setLineDash([5, 5]);
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.setLineDash([]);

    // 文字标签
    ctx.fillStyle = '#7F8C8D';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('前 AI 时代', x1, y1 - 15);
    ctx.fillText('0.35', x1, y1 + 20);

    ctx.fillStyle = '#2C5F68';
    ctx.font = 'bold 12px sans-serif';
    ctx.fillText('AI 时代', x2, y2 - 15);
    ctx.fillText('0.36', x2, y2 + 20);

    // Y 轴标签
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillStyle = '#7F8C8D';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('组间工资对数标准差', 0, 0);
    ctx.restore();
  }

  // 3. 事件监听：来源按钮
  const sourceBtns = document.querySelectorAll('[data-source]');
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const sourceId = btn.getAttribute('data-source');
      // 宿主内核处理桥接，此处不执行具体跳转，仅确保事件绑定
      if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sourceId]) {
         // 实际环境中由内核接管，此处仅做无操作占位以防报错，但不模拟行为
      }
    });
  });
})();
